/* ============================================================================
   B1 頁面管理「固定頁＋固定欄位」遷移（2026-10-07）——由 db/seed/generate-page-template-migration.py 產生，勿手改
   ① 刪除 test-draft-page ② 藍鯨 about/vision → about/vision-mission ③ 結構與版型不符的既有頁整份換成版型內容（新增版本、已發布）
   ④ 缺頁以種子內容建立（已發布）。冪等、單一交易。
   執行：sqlcmd -S <server> -d tcrfc_club -b -i db/migrations/20261007_page-templates.sql
   ============================================================================ */
SET XACT_ABORT ON;
BEGIN TRANSACTION;

-- ① 版型外的測試草稿頁（FK 為 ON DELETE CASCADE：i18n／區塊／版本隨頁面刪除）
DELETE FROM pages WHERE slug = N'test-draft-page';

-- ② 藍鯨願景頁 slug 統一
UPDATE p SET slug = N'about/vision-mission', updated_at = SYSUTCDATETIME()
FROM pages p JOIN clubs c ON c.id = p.club_id
WHERE c.code = N'bw' AND p.slug = N'about/vision'
  AND NOT EXISTS (SELECT 1 FROM pages x WHERE x.club_id = p.club_id AND x.slug = N'about/vision-mission');

-- ③④ tcrfc / about/our-story
BEGIN
  DECLARE @id uniqueidentifier = (SELECT p.id FROM pages p JOIN clubs c ON c.id = p.club_id WHERE c.code = N'tcrfc' AND p.slug = N'about/our-story');
  IF @id IS NULL
  BEGIN
    SET @id = NEWID();
    INSERT INTO pages (id, club_id, slug, status, published_at)
      VALUES (@id, (SELECT id FROM clubs WHERE code = N'tcrfc'), N'about/our-story', N'published', SYSUTCDATETIME());
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'我們的故事 Our Story｜關於台中磐石｜台中磐石足球俱樂部', N'台中磐石足球俱樂部（TCRFC）於 2024 年在台中成立。這裡收錄俱樂部從創立至今的沿革故事，完整內文正在整理中。');
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Our Story | About TCRFC | Taichung Rock FC', N'Taichung Rock FC (TCRFC) was founded in Taichung in 2024. This page will tell the club''s story from its founding to today; the full text is still being prepared.');
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"台中磐石足球俱樂部（Taichung Rock FC）於 2024 年在台中成立，同年即拿下全國乙級聯賽冠軍。俱樂部主場設於西屯足球場，以「在地扎根．放眼世界」為品牌主張，逐步建立起一線隊、學院與課程並行的發展體系。","en":"Taichung Rock FC was founded in Taichung in 2024 and won the National Second Division champions title in its first year. The club''s home ground is Xitun Football Field. With “LOCAL ROOTS. GLOBAL PATHWAYS.” as its brand promise, it has steadily built a development system in which the First Team, the Academy and our programs run side by side."}}', 0);
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, 1, N'{"seo":{"zh":{"seoTitle":"我們的故事 Our Story｜關於台中磐石｜台中磐石足球俱樂部","seoDescription":"台中磐石足球俱樂部（TCRFC）於 2024 年在台中成立。這裡收錄俱樂部從創立至今的沿革故事，完整內文正在整理中。"},"en":{"seoTitle":"Our Story | About TCRFC | Taichung Rock FC","seoDescription":"Taichung Rock FC (TCRFC) was founded in Taichung in 2024. This page will tell the club''s story from its founding to today; the full text is still being prepared."}},"blocks":[{"blockType":"text","content":{"body":{"zh":"台中磐石足球俱樂部（Taichung Rock FC）於 2024 年在台中成立，同年即拿下全國乙級聯賽冠軍。俱樂部主場設於西屯足球場，以「在地扎根．放眼世界」為品牌主張，逐步建立起一線隊、學院與課程並行的發展體系。","en":"Taichung Rock FC was founded in Taichung in 2024 and won the National Second Division champions title in its first year. The club''s home ground is Xitun Football Field. With “LOCAL ROOTS. GLOBAL PATHWAYS.” as its brand promise, it has steadily built a development system in which the First Team, the Academy and our programs run side by side."}}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
  END
  ELSE IF ISNULL((SELECT STRING_AGG(CAST(block_type AS nvarchar(max)), N',') WITHIN GROUP (ORDER BY sort_order) FROM page_blocks WHERE page_id = @id), N'') <> N'text'
  BEGIN
    DELETE FROM page_blocks WHERE page_id = @id;
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"台中磐石足球俱樂部（Taichung Rock FC）於 2024 年在台中成立，同年即拿下全國乙級聯賽冠軍。俱樂部主場設於西屯足球場，以「在地扎根．放眼世界」為品牌主張，逐步建立起一線隊、學院與課程並行的發展體系。","en":"Taichung Rock FC was founded in Taichung in 2024 and won the National Second Division champions title in its first year. The club''s home ground is Xitun Football Field. With “LOCAL ROOTS. GLOBAL PATHWAYS.” as its brand promise, it has steadily built a development system in which the First Team, the Academy and our programs run side by side."}}', 0);
    IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'zh-Hant')
      INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'我們的故事 Our Story｜關於台中磐石｜台中磐石足球俱樂部', N'台中磐石足球俱樂部（TCRFC）於 2024 年在台中成立。這裡收錄俱樂部從創立至今的沿革故事，完整內文正在整理中。');
    UPDATE pages_i18n SET seo_title = ISNULL(NULLIF(seo_title, N''), N'我們的故事 Our Story｜關於台中磐石｜台中磐石足球俱樂部'),
                          seo_description = ISNULL(NULLIF(seo_description, N''), N'台中磐石足球俱樂部（TCRFC）於 2024 年在台中成立。這裡收錄俱樂部從創立至今的沿革故事，完整內文正在整理中。')
      WHERE page_id = @id AND locale = N'zh-Hant';
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Our Story | About TCRFC | Taichung Rock FC', N'Taichung Rock FC (TCRFC) was founded in Taichung in 2024. This page will tell the club''s story from its founding to today; the full text is still being prepared.');
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, ISNULL((SELECT MAX(version_no) FROM page_versions WHERE page_id = @id), 0) + 1, N'{"seo":{"zh":{"seoTitle":"我們的故事 Our Story｜關於台中磐石｜台中磐石足球俱樂部","seoDescription":"台中磐石足球俱樂部（TCRFC）於 2024 年在台中成立。這裡收錄俱樂部從創立至今的沿革故事，完整內文正在整理中。"},"en":{"seoTitle":"Our Story | About TCRFC | Taichung Rock FC","seoDescription":"Taichung Rock FC (TCRFC) was founded in Taichung in 2024. This page will tell the club''s story from its founding to today; the full text is still being prepared."}},"blocks":[{"blockType":"text","content":{"body":{"zh":"台中磐石足球俱樂部（Taichung Rock FC）於 2024 年在台中成立，同年即拿下全國乙級聯賽冠軍。俱樂部主場設於西屯足球場，以「在地扎根．放眼世界」為品牌主張，逐步建立起一線隊、學院與課程並行的發展體系。","en":"Taichung Rock FC was founded in Taichung in 2024 and won the National Second Division champions title in its first year. The club''s home ground is Xitun Football Field. With “LOCAL ROOTS. GLOBAL PATHWAYS.” as its brand promise, it has steadily built a development system in which the First Team, the Academy and our programs run side by side."}}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
    UPDATE pages SET status = N'published', published_at = ISNULL(published_at, SYSUTCDATETIME()), updated_at = SYSUTCDATETIME() WHERE id = @id;
  END
END
GO

-- ③④ tcrfc / about/vision-mission
BEGIN
  DECLARE @id uniqueidentifier = (SELECT p.id FROM pages p JOIN clubs c ON c.id = p.club_id WHERE c.code = N'tcrfc' AND p.slug = N'about/vision-mission');
