  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'steps', N'{"items":[{"title":{"zh":"願景","en":"Vision"},"description":{"zh":"從台中出發，培育本土選手邁向職業舞台，成為在地榮耀的來源。","en":"Starting from Taichung, we develop local players for the professional stage and become a source of local pride."}},{"title":{"zh":"使命","en":"Mission"},"description":{"zh":"以扎實的訓練體系與國際連結，讓世界看見台灣足球。","en":"Through a solid training system and international connections, we let the world see Taiwan football."}}]}', 0);
