    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, ISNULL((SELECT MAX(version_no) FROM page_versions WHERE page_id = @id), 0) + 1, N'{"seo":{"zh":{"seoTitle":"願景與使命 Vision & Mission｜關於台中磐石｜台中磐石足球俱樂部","seoDescription":"台中磐石足球俱樂部的願景與使命：透過專業化培育體系，讓台中在地選手邁向職業舞台，並以足球讓世界看見台灣。"},"en":{"seoTitle":"Vision & Mission | About TCRFC | Taichung Rock FC","seoDescription":"The vision and mission of Taichung Rock FC: through a professional development system, we help local players in Taichung reach the professional stage and let the world see Taiwan football."}},"blocks":[{"blockType":"steps","content":{"items":[{"title":{"zh":"願景","en":"Vision"},"description":{"zh":"從台中出發，培育本土選手邁向職業舞台，成為在地榮耀的來源。","en":"Starting from Taichung, we develop local players for the professional stage and become a source of local pride."}},{"title":{"zh":"使命","en":"Mission"},"description":{"zh":"以扎實的訓練體系與國際連結，讓世界看見台灣足球。","en":"Through a solid training system and international connections, we let the world see Taiwan football."}}]}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
