-- ③④ tcrfc / about/philosophy
BEGIN
  DECLARE @id uniqueidentifier = (SELECT p.id FROM pages p JOIN clubs c ON c.id = p.club_id WHERE c.code = N'tcrfc' AND p.slug = N'about/philosophy');
  IF @id IS NULL
  BEGIN
    SET @id = NEWID();
    INSERT INTO pages (id, club_id, slug, status, published_at)
      VALUES (@id, (SELECT id FROM clubs WHERE code = N'tcrfc'), N'about/philosophy', N'published', SYSUTCDATETIME());
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'足球理念 Our Philosophy｜關於台中磐石｜台中磐石足球俱樂部', N'台中磐石足球俱樂部的足球理念與五大核心價值：以球員為本、追求卓越、國際發展、社區共好、誠信專業。');
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Our Philosophy | About TCRFC | Taichung Rock FC', N'The football philosophy and five core values of Taichung Rock FC: Players First, Excellence, Global Pathways, Community and Integrity.');
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"同時作為全站內容標籤，貫穿俱樂部各項訓練規劃與對外溝通。","en":"They also serve as content tags across the site, running through all of the club''s training plans and external communications."}}', 0);
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'steps', N'{"items":[{"title":{"zh":"以球員為本","en":"Players First"},"description":{"zh":"所有訓練規劃與資源配置，皆以球員的長期發展與福祉為核心考量。","en":"All training plans and resource allocation put players'' long-term development and wellbeing first."}},{"title":{"zh":"追求卓越","en":"Excellence"},"description":{"zh":"建立專業化訓練與教練體系，協助選手邁向職業舞台所需的實力與態度。","en":"We build a professional training and coaching system to help players develop the ability and mindset needed to reach the professional stage."}},{"title":{"zh":"國際發展","en":"Global Pathways"},"description":{"zh":"從台中出發、放眼世界，透過海外交流建立選手與職業舞台接軌的路徑。","en":"Starting from Taichung and looking to the world, we build pathways to the professional stage through international exchange."}},{"title":{"zh":"社區共好","en":"Community"},"description":{"zh":"紮根台中在地，成為社區認同與榮耀的來源，與球迷共同成長。","en":"Rooted in Taichung, we aim to be a source of local pride and identity, growing together with our fans."}},{"title":{"zh":"誠信專業","en":"Integrity"},"description":{"zh":"以誠信治理與專業制度，支撐俱樂部長期穩健發展。","en":"Honest governance and professional systems support the club''s long-term, steady development."}}]}', 1);
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, 1, N'{"seo":{"zh":{"seoTitle":"足球理念 Our Philosophy｜關於台中磐石｜台中磐石足球俱樂部","seoDescription":"台中磐石足球俱樂部的足球理念與五大核心價值：以球員為本、追求卓越、國際發展、社區共好、誠信專業。"},"en":{"seoTitle":"Our Philosophy | About TCRFC | Taichung Rock FC","seoDescription":"The football philosophy and five core values of Taichung Rock FC: Players First, Excellence, Global Pathways, Community and Integrity."}},"blocks":[{"blockType":"text","content":{"body":{"zh":"同時作為全站內容標籤，貫穿俱樂部各項訓練規劃與對外溝通。","en":"They also serve as content tags across the site, running through all of the club''s training plans and external communications."}}},{"blockType":"steps","content":{"items":[{"title":{"zh":"以球員為本","en":"Players First"},"description":{"zh":"所有訓練規劃與資源配置，皆以球員的長期發展與福祉為核心考量。","en":"All training plans and resource allocation put players'' long-term development and wellbeing first."}},{"title":{"zh":"追求卓越","en":"Excellence"},"description":{"zh":"建立專業化訓練與教練體系，協助選手邁向職業舞台所需的實力與態度。","en":"We build a professional training and coaching system to help players develop the ability and mindset needed to reach the professional stage."}},{"title":{"zh":"國際發展","en":"Global Pathways"},"description":{"zh":"從台中出發、放眼世界，透過海外交流建立選手與職業舞台接軌的路徑。","en":"Starting from Taichung and looking to the world, we build pathways to the professional stage through international exchange."}},{"title":{"zh":"社區共好","en":"Community"},"description":{"zh":"紮根台中在地，成為社區認同與榮耀的來源，與球迷共同成長。","en":"Rooted in Taichung, we aim to be a source of local pride and identity, growing together with our fans."}},{"title":{"zh":"誠信專業","en":"Integrity"},"description":{"zh":"以誠信治理與專業制度，支撐俱樂部長期穩健發展。","en":"Honest governance and professional systems support the club''s long-term, steady development."}}]}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
  END
  ELSE IF ISNULL((SELECT STRING_AGG(CAST(block_type AS nvarchar(max)), N',') WITHIN GROUP (ORDER BY sort_order) FROM page_blocks WHERE page_id = @id), N'') <> N'text,steps'
  BEGIN
