-- ③④ tcrfc / womens
BEGIN
  DECLARE @id uniqueidentifier = (SELECT p.id FROM pages p JOIN clubs c ON c.id = p.club_id WHERE c.code = N'tcrfc' AND p.slug = N'womens');
  IF @id IS NULL
  BEGIN
    SET @id = NEWID();
    INSERT INTO pages (id, club_id, slug, status, published_at)
      VALUES (@id, (SELECT id FROM clubs WHERE code = N'tcrfc'), N'womens', N'published', SYSUTCDATETIME());
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'女子足球 Women''s Football｜台中磐石足球俱樂部', N'台中藍鯨女子隊的介紹與官網入口。完整球員名單、教練陣容、賽程與成績請至台中藍鯨官方網站。');
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Women''s Football | Taichung Rock FC', N'An introduction to the Taichung Blue Whale women''s team and the entry point to its official website. For the full squad, coaching staff, fixtures and results, please visit the Taichung Blue Whale official website.');
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"隸屬於臺中市女子足球協會之台中藍鯨女子足球隊，簡稱為台中藍鯨，是台灣木蘭足球聯賽的球隊之一。以「藍鯨」作為象徵，代表追求更快、更堅強、更現代化的足球型態，重視團隊合作，鯨翅為台灣意象代表引領台灣足球向前邁進。台中藍鯨希望能帶動台中足球基層環境風氣，帶動中部地區女子足球的發展。","en":"The Taichung Blue Whale women''s football team belongs to the Taichung City Women''s Football Association, is known for short as Taichung Blue Whale, and is one of the teams in the Taiwan Mulan Football League. The blue whale is its symbol of a faster, stronger and more modern way of playing football, with an emphasis on teamwork, and the whale''s fin is an emblem of Taiwan, leading Taiwan football forward. Taichung Blue Whale hopes to lift the culture of grassroots football in Taichung and drive the development of women''s football in central Taiwan."}}', 0);
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, 1, N'{"seo":{"zh":{"seoTitle":"女子足球 Women''s Football｜台中磐石足球俱樂部","seoDescription":"台中藍鯨女子隊的介紹與官網入口。完整球員名單、教練陣容、賽程與成績請至台中藍鯨官方網站。"},"en":{"seoTitle":"Women''s Football | Taichung Rock FC","seoDescription":"An introduction to the Taichung Blue Whale women''s team and the entry point to its official website. For the full squad, coaching staff, fixtures and results, please visit the Taichung Blue Whale official website."}},"blocks":[{"blockType":"text","content":{"body":{"zh":"隸屬於臺中市女子足球協會之台中藍鯨女子足球隊，簡稱為台中藍鯨，是台灣木蘭足球聯賽的球隊之一。以「藍鯨」作為象徵，代表追求更快、更堅強、更現代化的足球型態，重視團隊合作，鯨翅為台灣意象代表引領台灣足球向前邁進。台中藍鯨希望能帶動台中足球基層環境風氣，帶動中部地區女子足球的發展。","en":"The Taichung Blue Whale women''s football team belongs to the Taichung City Women''s Football Association, is known for short as Taichung Blue Whale, and is one of the teams in the Taiwan Mulan Football League. The blue whale is its symbol of a faster, stronger and more modern way of playing football, with an emphasis on teamwork, and the whale''s fin is an emblem of Taiwan, leading Taiwan football forward. Taichung Blue Whale hopes to lift the culture of grassroots football in Taichung and drive the development of women''s football in central Taiwan."}}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
  END
  ELSE IF ISNULL((SELECT STRING_AGG(CAST(block_type AS nvarchar(max)), N',') WITHIN GROUP (ORDER BY sort_order) FROM page_blocks WHERE page_id = @id), N'') <> N'text'
  BEGIN
    DELETE FROM page_blocks WHERE page_id = @id;
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"隸屬於臺中市女子足球協會之台中藍鯨女子足球隊，簡稱為台中藍鯨，是台灣木蘭足球聯賽的球隊之一。以「藍鯨」作為象徵，代表追求更快、更堅強、更現代化的足球型態，重視團隊合作，鯨翅為台灣意象代表引領台灣足球向前邁進。台中藍鯨希望能帶動台中足球基層環境風氣，帶動中部地區女子足球的發展。","en":"The Taichung Blue Whale women''s football team belongs to the Taichung City Women''s Football Association, is known for short as Taichung Blue Whale, and is one of the teams in the Taiwan Mulan Football League. The blue whale is its symbol of a faster, stronger and more modern way of playing football, with an emphasis on teamwork, and the whale''s fin is an emblem of Taiwan, leading Taiwan football forward. Taichung Blue Whale hopes to lift the culture of grassroots football in Taichung and drive the development of women''s football in central Taiwan."}}', 0);
    IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'zh-Hant')
      INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'女子足球 Women''s Football｜台中磐石足球俱樂部', N'台中藍鯨女子隊的介紹與官網入口。完整球員名單、教練陣容、賽程與成績請至台中藍鯨官方網站。');
    UPDATE pages_i18n SET seo_title = ISNULL(NULLIF(seo_title, N''), N'女子足球 Women''s Football｜台中磐石足球俱樂部'),
                          seo_description = ISNULL(NULLIF(seo_description, N''), N'台中藍鯨女子隊的介紹與官網入口。完整球員名單、教練陣容、賽程與成績請至台中藍鯨官方網站。')
      WHERE page_id = @id AND locale = N'zh-Hant';
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Women''s Football | Taichung Rock FC', N'An introduction to the Taichung Blue Whale women''s team and the entry point to its official website. For the full squad, coaching staff, fixtures and results, please visit the Taichung Blue Whale official website.');
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, ISNULL((SELECT MAX(version_no) FROM page_versions WHERE page_id = @id), 0) + 1, N'{"seo":{"zh":{"seoTitle":"女子足球 Women''s Football｜台中磐石足球俱樂部","seoDescription":"台中藍鯨女子隊的介紹與官網入口。完整球員名單、教練陣容、賽程與成績請至台中藍鯨官方網站。"},"en":{"seoTitle":"Women''s Football | Taichung Rock FC","seoDescription":"An introduction to the Taichung Blue Whale women''s team and the entry point to its official website. For the full squad, coaching staff, fixtures and results, please visit the Taichung Blue Whale official website."}},"blocks":[{"blockType":"text","content":{"body":{"zh":"隸屬於臺中市女子足球協會之台中藍鯨女子足球隊，簡稱為台中藍鯨，是台灣木蘭足球聯賽的球隊之一。以「藍鯨」作為象徵，代表追求更快、更堅強、更現代化的足球型態，重視團隊合作，鯨翅為台灣意象代表引領台灣足球向前邁進。台中藍鯨希望能帶動台中足球基層環境風氣，帶動中部地區女子足球的發展。","en":"The Taichung Blue Whale women''s football team belongs to the Taichung City Women''s Football Association, is known for short as Taichung Blue Whale, and is one of the teams in the Taiwan Mulan Football League. The blue whale is its symbol of a faster, stronger and more modern way of playing football, with an emphasis on teamwork, and the whale''s fin is an emblem of Taiwan, leading Taiwan football forward. Taichung Blue Whale hopes to lift the culture of grassroots football in Taichung and drive the development of women''s football in central Taiwan."}}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
