  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'steps', N'{"items":[{"title":{"zh":"為何合作","en":"Why Partner"},"description":{"zh":"台中磐石是台中在地唯一的企業甲級足球俱樂部，是品牌走進運動與社區場域的直接管道。","en":"Taichung Rock FC is the only club in Taichung competing in the top-tier corporate league, giving brands a direct route into sport and the local community."}},{"title":{"zh":"受眾分析","en":"Audience Analysis"},"description":{"zh":"涵蓋一線隊球迷、學院學員家庭與賽事現場觀眾，詳細數據見下方。","en":"Covers First Team fans, Academy student families and matchday crowds. Detailed figures are below."}},{"title":{"zh":"品牌曝光","en":"Brand Exposure"},"description":{"zh":"球衣、場邊看板、官網與社群通路曝光，讓品牌與職業足球賽事同框。","en":"Exposure on the kit, pitchside boards, our website and social media channels puts your brand alongside professional football fixtures."}},{"title":{"zh":"社會影響力","en":"Social Impact"},"description":{"zh":"結合社區足球日與慈善活動，讓品牌參與有意義的在地社會實踐。","en":"Community football days and charity activities let your brand take part in meaningful local social action."}},{"title":{"zh":"中介影響力","en":"Community Reach"},"description":{"zh":"透過學院與課程與家庭、學校建立長期信任關係，擴大品牌口碑觸及。","en":"Through the Academy and our programs, build long-term trust with families and schools and widen your brand''s word-of-mouth reach."}},{"title":{"zh":"國際影響力","en":"International Impact"},"description":{"zh":"藉由國際交流與海外拓展計畫，讓品牌隨台中磐石球員的腳步走向世界。","en":"Through international exchange and overseas expansion programs, let your brand travel the world with Taichung Rock FC''s players."}}]}', 0);
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"完整受眾與社群數據報告可於洽談合作時提供，歡迎聯絡商務部索取最新資料。","en":"The full audience and social media data report is available when we discuss a partnership. Please contact our Partnerships Department for the latest figures."}}', 1);
