-- ③④ tcrfc / charity/commitment
BEGIN
  DECLARE @id uniqueidentifier = (SELECT p.id FROM pages p JOIN clubs c ON c.id = p.club_id WHERE c.code = N'tcrfc' AND p.slug = N'charity/commitment');
  IF @id IS NULL
  BEGIN
    SET @id = NEWID();
    INSERT INTO pages (id, club_id, slug, status, published_at)
      VALUES (@id, (SELECT id FROM clubs WHERE code = N'tcrfc'), N'charity/commitment', N'published', SYSUTCDATETIME());
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'慈善理念與投入領域 Our Commitment｜慈善與社會影響｜台中磐石足球俱樂部', N'台中磐石足球俱樂部的慈善理念與四大投入領域：青少年扶助、偏鄉足球、弱勢家庭與公益義賽，實踐 Community 社區共好核心價值。');
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Our Commitment and Focus Areas | Charity & Impact | Taichung Rock FC', N'The charitable philosophy and four focus areas of Taichung Rock FC: youth support, rural football, disadvantaged families and charity matches, putting our core value of Community into practice.');
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"台中磐石足球俱樂部自 2024 年成立以來，將「Community 社區共好」列為五大核心價值之一，相信足球能為社區帶來的影響不只在球場上。我們相信優質的足球資源不該只集中在少數人身上，因此持續尋找機會，把訓練、場地與人才帶到需要的地方。","en":"Since Taichung Rock FC was founded in 2024, Community has been one of our five core values. We believe the impact football can have on a community goes well beyond the pitch. We also believe that good football resources should not be concentrated in the hands of a few, so we keep looking for opportunities to bring training, facilities and talent to the places that need them."}}', 0);
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"以下四大領域為規劃書明列的公益投入方向，各領域詳細計畫請見 11.2 慈善計畫。","en":"The four areas below are our public-interest priorities. For the programs in each area, see 11.2 Charity Programs."}}', 1);
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'steps', N'{"items":[{"title":{"zh":"青少年扶助","en":"Youth Support"},"description":{"zh":"支持經濟弱勢或資源不足地區的青少年參與足球運動，降低參與門檻。","en":"Supporting young people from economically disadvantaged or under-resourced areas to take part in football, and lowering the barriers to participation."}},{"title":{"zh":"偏鄉足球","en":"Rural Football"},"description":{"zh":"將教練資源與訓練機會帶到偏遠地區的學校與社區，拉近城鄉足球資源落差。","en":"Bringing coaching resources and training opportunities to schools and communities in remote areas, narrowing the gap in football resources between cities and the countryside."}},{"title":{"zh":"弱勢家庭","en":"Family Support"},"description":{"zh":"與在地社福單位合作，提供弱勢家庭孩子參與足球活動的機會與必要物資。","en":"Working with local social welfare organisations to give children from disadvantaged families the chance to take part in football activities, along with the necessary supplies."}},{"title":{"zh":"公益義賽","en":"Charity Matches"},"description":{"zh":"舉辦或參與公益義賽，將活動收益或關注度轉化為對特定公益團體的實質支持。","en":"Organising or taking part in charity matches, turning event proceeds or attention into real support for specific charities."}}]}', 2);
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, 1, N'{"seo":{"zh":{"seoTitle":"慈善理念與投入領域 Our Commitment｜慈善與社會影響｜台中磐石足球俱樂部","seoDescription":"台中磐石足球俱樂部的慈善理念與四大投入領域：青少年扶助、偏鄉足球、弱勢家庭與公益義賽，實踐 Community 社區共好核心價值。"},"en":{"seoTitle":"Our Commitment and Focus Areas | Charity & Impact | Taichung Rock FC","seoDescription":"The charitable philosophy and four focus areas of Taichung Rock FC: youth support, rural football, disadvantaged families and charity matches, putting our core value of Community into practice."}},"blocks":[{"blockType":"text","content":{"body":{"zh":"台中磐石足球俱樂部自 2024 年成立以來，將「Community 社區共好」列為五大核心價值之一，相信足球能為社區帶來的影響不只在球場上。我們相信優質的足球資源不該只集中在少數人身上，因此持續尋找機會，把訓練、場地與人才帶到需要的地方。","en":"Since Taichung Rock FC was founded in 2024, Community has been one of our five core values. We believe the impact football can have on a community goes well beyond the pitch. We also believe that good football resources should not be concentrated in the hands of a few, so we keep looking for opportunities to bring training, facilities and talent to the places that need them."}}},{"blockType":"text","content":{"body":{"zh":"以下四大領域為規劃書明列的公益投入方向，各領域詳細計畫請見 11.2 慈善計畫。","en":"The four areas below are our public-interest priorities. For the programs in each area, see 11.2 Charity Programs."}}},{"blockType":"steps","content":{"items":[{"title":{"zh":"青少年扶助","en":"Youth Support"},"description":{"zh":"支持經濟弱勢或資源不足地區的青少年參與足球運動，降低參與門檻。","en":"Supporting young people from economically disadvantaged or under-resourced areas to take part in football, and lowering the barriers to participation."}},{"title":{"zh":"偏鄉足球","en":"Rural Football"},"description":{"zh":"將教練資源與訓練機會帶到偏遠地區的學校與社區，拉近城鄉足球資源落差。","en":"Bringing coaching resources and training opportunities to schools and communities in remote areas, narrowing the gap in football resources between cities and the countryside."}},{"title":{"zh":"弱勢家庭","en":"Family Support"},"description":{"zh":"與在地社福單位合作，提供弱勢家庭孩子參與足球活動的機會與必要物資。","en":"Working with local social welfare organisations to give children from disadvantaged families the chance to take part in football activities, along with the necessary supplies."}},{"title":{"zh":"公益義賽","en":"Charity Matches"},"description":{"zh":"舉辦或參與公益義賽，將活動收益或關注度轉化為對特定公益團體的實質支持。","en":"Organising or taking part in charity matches, turning event proceeds or attention into real support for specific charities."}}]}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
  END
  ELSE IF ISNULL((SELECT STRING_AGG(CAST(block_type AS nvarchar(max)), N',') WITHIN GROUP (ORDER BY sort_order) FROM page_blocks WHERE page_id = @id), N'') <> N'text,text,steps'
  BEGIN
    DELETE FROM page_blocks WHERE page_id = @id;
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"台中磐石足球俱樂部自 2024 年成立以來，將「Community 社區共好」列為五大核心價值之一，相信足球能為社區帶來的影響不只在球場上。我們相信優質的足球資源不該只集中在少數人身上，因此持續尋找機會，把訓練、場地與人才帶到需要的地方。","en":"Since Taichung Rock FC was founded in 2024, Community has been one of our five core values. We believe the impact football can have on a community goes well beyond the pitch. We also believe that good football resources should not be concentrated in the hands of a few, so we keep looking for opportunities to bring training, facilities and talent to the places that need them."}}', 0);
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"以下四大領域為規劃書明列的公益投入方向，各領域詳細計畫請見 11.2 慈善計畫。","en":"The four areas below are our public-interest priorities. For the programs in each area, see 11.2 Charity Programs."}}', 1);
