-- ③④ bw / about/vision-mission
BEGIN
  DECLARE @id uniqueidentifier = (SELECT p.id FROM pages p JOIN clubs c ON c.id = p.club_id WHERE c.code = N'bw' AND p.slug = N'about/vision-mission');
  IF @id IS NULL
  BEGIN
    SET @id = NEWID();
    INSERT INTO pages (id, club_id, slug, status, published_at)
      VALUES (@id, (SELECT id FROM clubs WHERE code = N'bw'), N'about/vision-mission', N'published', SYSUTCDATETIME());
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'發展願景｜關於台中藍鯨｜台中藍鯨女子足球隊', N'台中藍鯨女子足球隊的發展願景：無止盡的探索、不怕難的堅韌、更細膩的態度、最真實的影響、更深遠之目的。');
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Development Vision | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club', N'The development vision of Taichung Blue Whale Women''s Football Club: endless exploration, resilience that fears no difficulty, a more refined attitude, the most genuine impact and a deeper purpose.');
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'steps', N'{"items":[{"title":{"zh":"無止盡的探索","en":"Endless Exploration"},"description":{"zh":"提昇及普及大台中足球水準，吸收更專業精進足球技術，追上亞洲足球技術水平迎接世界潮流。","en":"Raise and popularise the standard of football in greater Taichung, absorb more professional and refined football skills, catch up with the technical level of Asian football and meet the global trend."}},{"title":{"zh":"不怕難的堅韌","en":"Resilience That Fears No Difficulty"},"description":{"zh":"創造足球運動文化與風氣，以球迷為本讓足球比賽呈現更有水準，場內技術提升，場外足球比賽氛圍更加提升。","en":"Create a football culture and atmosphere with fans at the centre, so that matches reach a higher standard: better technique on the pitch and a livelier matchday atmosphere off it."}},{"title":{"zh":"更細膩的態度","en":"A More Refined Attitude"},"description":{"zh":"增加足球選手發展管道，讓選手有更好的發展空間，家長支持，學校支持，政府支持，產業支持，民眾支持。","en":"Widen the pathways for football players so they have more room to develop, with the support of parents, schools, government, industry and the public."}},{"title":{"zh":"最真實的影響","en":"The Most Genuine Impact"},"description":{"zh":"建立台中為台灣足球之都的美名與榮耀，健康正向的足球風氣，連結喜愛足球運動的球迷及選手所追求的足球夢想。","en":"Build Taichung''s reputation and pride as the capital of Taiwan football, with a healthy and positive football culture that connects fans who love the sport with the football dreams that players pursue."}},{"title":{"zh":"更深遠之目的","en":"A Deeper Purpose"},"description":{"zh":"持續回饋社會，致力為人們創造更美好的生活，深信我們能帶來改變，幫助人們以全新的方式彼此分享與連結，讓世界更加和諧。","en":"Keep giving back to society and strive to create a better life for people. We believe we can bring change, helping people share and connect with one another in new ways and making the world more harmonious."}}]}', 0);
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, 1, N'{"seo":{"zh":{"seoTitle":"發展願景｜關於台中藍鯨｜台中藍鯨女子足球隊","seoDescription":"台中藍鯨女子足球隊的發展願景：無止盡的探索、不怕難的堅韌、更細膩的態度、最真實的影響、更深遠之目的。"},"en":{"seoTitle":"Development Vision | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club","seoDescription":"The development vision of Taichung Blue Whale Women''s Football Club: endless exploration, resilience that fears no difficulty, a more refined attitude, the most genuine impact and a deeper purpose."}},"blocks":[{"blockType":"steps","content":{"items":[{"title":{"zh":"無止盡的探索","en":"Endless Exploration"},"description":{"zh":"提昇及普及大台中足球水準，吸收更專業精進足球技術，追上亞洲足球技術水平迎接世界潮流。","en":"Raise and popularise the standard of football in greater Taichung, absorb more professional and refined football skills, catch up with the technical level of Asian football and meet the global trend."}},{"title":{"zh":"不怕難的堅韌","en":"Resilience That Fears No Difficulty"},"description":{"zh":"創造足球運動文化與風氣，以球迷為本讓足球比賽呈現更有水準，場內技術提升，場外足球比賽氛圍更加提升。","en":"Create a football culture and atmosphere with fans at the centre, so that matches reach a higher standard: better technique on the pitch and a livelier matchday atmosphere off it."}},{"title":{"zh":"更細膩的態度","en":"A More Refined Attitude"},"description":{"zh":"增加足球選手發展管道，讓選手有更好的發展空間，家長支持，學校支持，政府支持，產業支持，民眾支持。","en":"Widen the pathways for football players so they have more room to develop, with the support of parents, schools, government, industry and the public."}},{"title":{"zh":"最真實的影響","en":"The Most Genuine Impact"},"description":{"zh":"建立台中為台灣足球之都的美名與榮耀，健康正向的足球風氣，連結喜愛足球運動的球迷及選手所追求的足球夢想。","en":"Build Taichung''s reputation and pride as the capital of Taiwan football, with a healthy and positive football culture that connects fans who love the sport with the football dreams that players pursue."}},{"title":{"zh":"更深遠之目的","en":"A Deeper Purpose"},"description":{"zh":"持續回饋社會，致力為人們創造更美好的生活，深信我們能帶來改變，幫助人們以全新的方式彼此分享與連結，讓世界更加和諧。","en":"Keep giving back to society and strive to create a better life for people. We believe we can bring change, helping people share and connect with one another in new ways and making the world more harmonious."}}]}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
  END
  ELSE IF ISNULL((SELECT STRING_AGG(CAST(block_type AS nvarchar(max)), N',') WITHIN GROUP (ORDER BY sort_order) FROM page_blocks WHERE page_id = @id), N'') <> N'steps'
  BEGIN
    DELETE FROM page_blocks WHERE page_id = @id;
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'steps', N'{"items":[{"title":{"zh":"無止盡的探索","en":"Endless Exploration"},"description":{"zh":"提昇及普及大台中足球水準，吸收更專業精進足球技術，追上亞洲足球技術水平迎接世界潮流。","en":"Raise and popularise the standard of football in greater Taichung, absorb more professional and refined football skills, catch up with the technical level of Asian football and meet the global trend."}},{"title":{"zh":"不怕難的堅韌","en":"Resilience That Fears No Difficulty"},"description":{"zh":"創造足球運動文化與風氣，以球迷為本讓足球比賽呈現更有水準，場內技術提升，場外足球比賽氛圍更加提升。","en":"Create a football culture and atmosphere with fans at the centre, so that matches reach a higher standard: better technique on the pitch and a livelier matchday atmosphere off it."}},{"title":{"zh":"更細膩的態度","en":"A More Refined Attitude"},"description":{"zh":"增加足球選手發展管道，讓選手有更好的發展空間，家長支持，學校支持，政府支持，產業支持，民眾支持。","en":"Widen the pathways for football players so they have more room to develop, with the support of parents, schools, government, industry and the public."}},{"title":{"zh":"最真實的影響","en":"The Most Genuine Impact"},"description":{"zh":"建立台中為台灣足球之都的美名與榮耀，健康正向的足球風氣，連結喜愛足球運動的球迷及選手所追求的足球夢想。","en":"Build Taichung''s reputation and pride as the capital of Taiwan football, with a healthy and positive football culture that connects fans who love the sport with the football dreams that players pursue."}},{"title":{"zh":"更深遠之目的","en":"A Deeper Purpose"},"description":{"zh":"持續回饋社會，致力為人們創造更美好的生活，深信我們能帶來改變，幫助人們以全新的方式彼此分享與連結，讓世界更加和諧。","en":"Keep giving back to society and strive to create a better life for people. We believe we can bring change, helping people share and connect with one another in new ways and making the world more harmonious."}}]}', 0);
    IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'zh-Hant')
      INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'發展願景｜關於台中藍鯨｜台中藍鯨女子足球隊', N'台中藍鯨女子足球隊的發展願景：無止盡的探索、不怕難的堅韌、更細膩的態度、最真實的影響、更深遠之目的。');
    UPDATE pages_i18n SET seo_title = ISNULL(NULLIF(seo_title, N''), N'發展願景｜關於台中藍鯨｜台中藍鯨女子足球隊'),
                          seo_description = ISNULL(NULLIF(seo_description, N''), N'台中藍鯨女子足球隊的發展願景：無止盡的探索、不怕難的堅韌、更細膩的態度、最真實的影響、更深遠之目的。')
      WHERE page_id = @id AND locale = N'zh-Hant';
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Development Vision | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club', N'The development vision of Taichung Blue Whale Women''s Football Club: endless exploration, resilience that fears no difficulty, a more refined attitude, the most genuine impact and a deeper purpose.');
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, ISNULL((SELECT MAX(version_no) FROM page_versions WHERE page_id = @id), 0) + 1, N'{"seo":{"zh":{"seoTitle":"發展願景｜關於台中藍鯨｜台中藍鯨女子足球隊","seoDescription":"台中藍鯨女子足球隊的發展願景：無止盡的探索、不怕難的堅韌、更細膩的態度、最真實的影響、更深遠之目的。"},"en":{"seoTitle":"Development Vision | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club","seoDescription":"The development vision of Taichung Blue Whale Women''s Football Club: endless exploration, resilience that fears no difficulty, a more refined attitude, the most genuine impact and a deeper purpose."}},"blocks":[{"blockType":"steps","content":{"items":[{"title":{"zh":"無止盡的探索","en":"Endless Exploration"},"description":{"zh":"提昇及普及大台中足球水準，吸收更專業精進足球技術，追上亞洲足球技術水平迎接世界潮流。","en":"Raise and popularise the standard of football in greater Taichung, absorb more professional and refined football skills, catch up with the technical level of Asian football and meet the global trend."}},{"title":{"zh":"不怕難的堅韌","en":"Resilience That Fears No Difficulty"},"description":{"zh":"創造足球運動文化與風氣，以球迷為本讓足球比賽呈現更有水準，場內技術提升，場外足球比賽氛圍更加提升。","en":"Create a football culture and atmosphere with fans at the centre, so that matches reach a higher standard: better technique on the pitch and a livelier matchday atmosphere off it."}},{"title":{"zh":"更細膩的態度","en":"A More Refined Attitude"},"description":{"zh":"增加足球選手發展管道，讓選手有更好的發展空間，家長支持，學校支持，政府支持，產業支持，民眾支持。","en":"Widen the pathways for football players so they have more room to develop, with the support of parents, schools, government, industry and the public."}},{"title":{"zh":"最真實的影響","en":"The Most Genuine Impact"},"description":{"zh":"建立台中為台灣足球之都的美名與榮耀，健康正向的足球風氣，連結喜愛足球運動的球迷及選手所追求的足球夢想。","en":"Build Taichung''s reputation and pride as the capital of Taiwan football, with a healthy and positive football culture that connects fans who love the sport with the football dreams that players pursue."}},{"title":{"zh":"更深遠之目的","en":"A Deeper Purpose"},"description":{"zh":"持續回饋社會，致力為人們創造更美好的生活，深信我們能帶來改變，幫助人們以全新的方式彼此分享與連結，讓世界更加和諧。","en":"Keep giving back to society and strive to create a better life for people. We believe we can bring change, helping people share and connect with one another in new ways and making the world more harmonious."}}]}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
