-- ③④ bw / about/philosophy
BEGIN
  DECLARE @id uniqueidentifier = (SELECT p.id FROM pages p JOIN clubs c ON c.id = p.club_id WHERE c.code = N'bw' AND p.slug = N'about/philosophy');
  IF @id IS NULL
  BEGIN
    SET @id = NEWID();
    INSERT INTO pages (id, club_id, slug, status, published_at)
      VALUES (@id, (SELECT id FROM clubs WHERE code = N'bw'), N'about/philosophy', N'published', SYSUTCDATETIME());
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'俱樂部口號與培訓精神｜關於台中藍鯨｜台中藍鯨女子足球隊', N'台中藍鯨女子足球隊的俱樂部口號與培訓精神，以及隊徽「藍鯨」象徵的設計理念。');
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Club Slogan and Training Spirit | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club', N'The club slogan and training spirit of Taichung Blue Whale Women''s Football Club, and the design concept behind the blue whale on the club crest.');
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'quote', N'{"text":{"zh":"以「藍鯨」作為象徵，代表追求更快、更堅強、更現代化的足球型態、重視團隊合作，鯨翅為台灣意象代表引領台灣足球向前邁進。","en":"The blue whale is our symbol, representing a faster, stronger and more modern style of football with an emphasis on teamwork; the whale''s fin is an emblem of Taiwan, leading Taiwan football forward."},"attribution":{"zh":"隊徽理念","en":"Crest Concept"}}', 0);
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'quote', N'{"text":{"zh":"藍色的天空是我們心中夢想的方向，閃爍的陽光是走向夢想的力量，草地上揮灑汗水是成長過往 堅定信仰，有你在身旁 就不再徬徨，此時此刻，我們與我們的球迷站在一起。一起迎向世界。","en":"The blue sky is the direction of the dreams in our hearts, the glittering sunlight is the strength that carries us towards them, and the sweat shed on the grass is our growth and our steadfast belief. With you by our side we are no longer lost. Right now, we stand together with our fans, and face the world together."},"attribution":{"zh":"俱樂部口號","en":"Club Slogan"}}', 1);
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'quote', N'{"text":{"zh":"別害怕 勇敢去闖，邁開步伐乘風破浪，就算遍體鱗傷 也要逆風飛翔，抬起頭 夢在前方，越過那重重的高牆 沒有誰能阻擋，眼神越是發光，世界都是我的舞台。","en":"Do not be afraid; be brave and go for it. Stride forward and ride the waves; even if you are covered in scars, fly into the wind. Lift your head, the dream is ahead. Cross those high walls, and no one can stop us. The brighter our eyes shine, the more the whole world is our stage."},"attribution":{"zh":"培訓精神","en":"Training Spirit"}}', 2);
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, 1, N'{"seo":{"zh":{"seoTitle":"俱樂部口號與培訓精神｜關於台中藍鯨｜台中藍鯨女子足球隊","seoDescription":"台中藍鯨女子足球隊的俱樂部口號與培訓精神，以及隊徽「藍鯨」象徵的設計理念。"},"en":{"seoTitle":"Club Slogan and Training Spirit | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club","seoDescription":"The club slogan and training spirit of Taichung Blue Whale Women''s Football Club, and the design concept behind the blue whale on the club crest."}},"blocks":[{"blockType":"quote","content":{"text":{"zh":"以「藍鯨」作為象徵，代表追求更快、更堅強、更現代化的足球型態、重視團隊合作，鯨翅為台灣意象代表引領台灣足球向前邁進。","en":"The blue whale is our symbol, representing a faster, stronger and more modern style of football with an emphasis on teamwork; the whale''s fin is an emblem of Taiwan, leading Taiwan football forward."},"attribution":{"zh":"隊徽理念","en":"Crest Concept"}}},{"blockType":"quote","content":{"text":{"zh":"藍色的天空是我們心中夢想的方向，閃爍的陽光是走向夢想的力量，草地上揮灑汗水是成長過往 堅定信仰，有你在身旁 就不再徬徨，此時此刻，我們與我們的球迷站在一起。一起迎向世界。","en":"The blue sky is the direction of the dreams in our hearts, the glittering sunlight is the strength that carries us towards them, and the sweat shed on the grass is our growth and our steadfast belief. With you by our side we are no longer lost. Right now, we stand together with our fans, and face the world together."},"attribution":{"zh":"俱樂部口號","en":"Club Slogan"}}},{"blockType":"quote","content":{"text":{"zh":"別害怕 勇敢去闖，邁開步伐乘風破浪，就算遍體鱗傷 也要逆風飛翔，抬起頭 夢在前方，越過那重重的高牆 沒有誰能阻擋，眼神越是發光，世界都是我的舞台。","en":"Do not be afraid; be brave and go for it. Stride forward and ride the waves; even if you are covered in scars, fly into the wind. Lift your head, the dream is ahead. Cross those high walls, and no one can stop us. The brighter our eyes shine, the more the whole world is our stage."},"attribution":{"zh":"培訓精神","en":"Training Spirit"}}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
  END
  ELSE IF ISNULL((SELECT STRING_AGG(CAST(block_type AS nvarchar(max)), N',') WITHIN GROUP (ORDER BY sort_order) FROM page_blocks WHERE page_id = @id), N'') <> N'quote,quote,quote'
  BEGIN
    DELETE FROM page_blocks WHERE page_id = @id;
