    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Governance | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club', N'Governance information and a download area for the public documents of Taichung Blue Whale Women''s Football Club. Content is updated regularly.');
    INSERT INTO page_versions (id, page_id, version_no, snapshot, preview_token)
      VALUES (NEWID(), @id, ISNULL((SELECT MAX(version_no) FROM page_versions WHERE page_id = @id), 0) + 1, N'{"seo":{"zh":{"seoTitle":"治理與管理｜關於台中藍鯨｜台中藍鯨女子足球隊","seoDescription":"台中藍鯨女子足球隊治理相關資訊與公開文件下載區，內容持續更新中。"},"en":{"seoTitle":"Governance | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club","seoDescription":"Governance information and a download area for the public documents of Taichung Blue Whale Women''s Football Club. Content is updated regularly."}},"blocks":[{"blockType":"text","content":{"body":{"zh":"目前尚無可供下載的公開文件。","en":"There are no public documents available to download at the moment."}}}]}', LOWER(CONVERT(varchar(64), CRYPT_GEN_RANDOM(32), 2)));
    UPDATE pages SET status = N'published', published_at = ISNULL(published_at, SYSUTCDATETIME()), updated_at = SYSUTCDATETIME() WHERE id = @id;
  END
END
GO

-- ③④ bw / about/history
BEGIN
  DECLARE @id uniqueidentifier = (SELECT p.id FROM pages p JOIN clubs c ON c.id = p.club_id WHERE c.code = N'bw' AND p.slug = N'about/history');
  IF @id IS NULL
  BEGIN
    SET @id = NEWID();
    INSERT INTO pages (id, club_id, slug, status, published_at)
      VALUES (@id, (SELECT id FROM clubs WHERE code = N'bw'), N'about/history', N'published', SYSUTCDATETIME());
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'zh-Hant', N'俱樂部歷程｜關於台中藍鯨｜台中藍鯨女子足球隊', N'台中藍鯨女子足球隊 2014～2025 年逐年沿革，整理自舊官網公開內容。');
  IF NOT EXISTS (SELECT 1 FROM pages_i18n WHERE page_id = @id AND locale = N'en')
    INSERT INTO pages_i18n (page_id, locale, seo_title, seo_description) VALUES (@id, N'en', N'Club History | About Taichung Blue Whale | Taichung Blue Whale Women''s Football Club', N'A year-by-year history of Taichung Blue Whale Women''s Football Club from 2014 to 2025, compiled from content published on the former official website.');
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'timeline', N'{"items":[{"date":"2014","title":{"zh":"2014 年","en":"2014"},"description":{"zh":"籌組台中藍鯨女子足球隊參加木蘭聯賽\n參加第一屆台灣木蘭足球聯賽\nFB 粉絲人數 1200 人\n台灣體育運動大學小型人工草足球場完成","en":"Formed the Taichung Blue Whale women''s football team to compete in the Mulan League\nTook part in the 1st Taiwan Mulan Football League\nFacebook followers reached 1,200\nSmall-sided artificial-turf football pitch completed at the National Taiwan Sport University"}},{"date":"2015","title":{"zh":"2015 年","en":"2015"},"description":{"zh":"參加第二屆台灣木蘭足球聯賽\n協助台中市五權國中女足隊成立\n承接辦理 D 級教練講習","en":"Took part in the 2nd Taiwan Mulan Football League\nHelped establish the girls'' football team at 五權國中, a junior high school in Taichung\nTook on the organisation of a D-level coaching course"}},{"date":"2016","title":{"zh":"2016 年","en":"2016"},"description":{"zh":"參加第三屆台灣木蘭足球聯賽\n成立中部菁英女子訓練站\n首次舉辦 AFC 女子足球節","en":"Took part in the 3rd Taiwan Mulan Football League\nEstablished the Central Taiwan Elite Women''s Training Station\nHeld the AFC Women''s Football Day for the first time"}},{"date":"2017","title":{"zh":"2017 年","en":"2017"},"description":{"zh":"參加第三屆台灣木蘭足球聯賽\n舉辦第一屆藍鯨盃足球賽\n菁英女子足球訓練站改名中部訓練站\n聘請 JFA S 級教練 堀野博幸擔任一線隊總教練\n舉辦地區性教練講習\n台中北屯太原足球場啟用\n隊史第一座台灣木蘭聯賽冠軍\nFB 粉絲人數達 6500 人","en":"Took part in the 3rd Taiwan Mulan Football League\nHeld the 1st Blue Whale Cup football tournament\nRenamed the Elite Women''s Football Training Station the Central Training Station\nAppointed JFA S-level coach 堀野博幸 as First Team head coach\nHeld a regional coaching course\nTaichung Beitun Taiyuan Football Field opened\nFirst Taiwan Mulan League title in club history\nFacebook followers reached 6,500"}},{"date":"2018","title":{"zh":"2018 年","en":"2018"},"description":{"zh":"參加第四屆台灣木蘭足球聯賽\n成立台中藍鯨足球學校\n中部訓練站更名為藍鯨中部足球訓練站\n第一位職業選手包欣玄加入台中藍鯨\n協助台中市惠文高中成立女足隊成立\n隊史第二座台灣木蘭聯賽冠軍","en":"Took part in the 4th Taiwan Mulan Football League\nFounded the Taichung Blue Whale Football School\nRenamed the Central Training Station the Blue Whale Central Football Training Station\nFirst professional player 包欣玄 joined Taichung Blue Whale\nHelped establish the girls'' football team at 惠文高中, a senior high school in Taichung\nSecond Taiwan Mulan League title in club history"}},{"date":"2019","title":{"zh":"2019 年","en":"2019"},"description":{"zh":"參加第五屆台灣木蘭足球聯賽\n守門員蔡明容輸出旅外日本成功\n第一位日本選手田中麻帆加入\n爭取台中足球園區興建\n成立電競小隊參加 PES2020 世界盃\n隊史第三座台灣木蘭聯賽冠軍\n聯賽第一次藍鯨主場售票\n通過 AFC CLUB License 俱樂部認證\n總教練呂桂花獲得 AFC2019 草根領袖獎\n首次全年度主場舉辦主題日\n成立藍鯨女孩啦啦隊\n承接運動 i 台灣-運動熱區推廣計畫","en":"Took part in the 5th Taiwan Mulan Football League\nGoalkeeper 蔡明容 successfully moved abroad to Japan\nFirst Japanese player 田中麻帆 joined\nCampaigned for the construction of a Taichung football park\nFormed an esports squad to compete in the PES2020 World Cup\nThird Taiwan Mulan League title in club history\nFirst time the club sold tickets for a league home match\nPassed the AFC Club Licence accreditation\nHead coach 呂桂花 won the AFC 2019 Grassroots Leader Award\nFirst full season of themed days at home matches\nFounded the Blue Whale Girls cheerleading squad\nTook on the Sports iTaiwan sports hotspot promotion programme"}},{"date":"2020","title":{"zh":"2020 年","en":"2020"},"description":{"zh":"參加第六屆台灣木蘭足球聯賽\n第一位香港籍選手吳卓蔚加入\n第一位美國籍選手瑪芮兒加入\n守門員程思瑜輸出旅外日本成功\n選手蘇育萱輸出旅外日本成功\n聯賽藍鯨主場售票\n台中藍鯨 U15 女子足球隊參加第一屆台灣青年聯賽\n隊史第一座台灣木蘭聯賽亞軍\n承接運動 i 台灣-運動熱區推廣計畫","en":"Took part in the 6th Taiwan Mulan Football League\nFirst Hong Kong player 吳卓蔚 joined\nFirst American player 瑪芮兒 joined\nGoalkeeper 程思瑜 successfully moved abroad to Japan\nPlayer 蘇育萱 successfully moved abroad to Japan\nSold tickets for league home matches\nThe Taichung Blue Whale U15 girls'' team took part in the 1st Taiwan Youth League\nFirst Taiwan Mulan League runners-up finish in club history\nTook on the Sports iTaiwan sports hotspot promotion programme"}},{"date":"2021","title":{"zh":"2021 年","en":"2021"},"description":{"zh":"參加第八屆台灣木蘭足球聯賽\n第二位日本籍選手日高偉織加入\n第一位泰國籍選手皮薩邁頌賽加入\n第一位泰國籍守門員納塔魯亞牧塔納維奇加入\n隊史第四座台灣木蘭聯賽冠軍\n隊史第一座台灣木蘭聯賽盃 MLC 冠軍\n台中藍鯨 U15 女子足球隊參加第二屆台灣青年聯賽\n台中藍鯨 U18 女子足球隊參加第二屆台灣青年聯賽\n承接運動 i 台灣-運動熱區推廣計畫","en":"Took part in the 8th Taiwan Mulan Football League\nSecond Japanese player 日高偉織 joined\nFirst Thai player 皮薩邁頌賽 joined\nFirst Thai goalkeeper 納塔魯亞牧塔納維奇 joined\nFourth Taiwan Mulan League title in club history\nFirst Taiwan Mulan League Cup (MLC) title in club history\nThe Taichung Blue Whale U15 girls'' team took part in the 2nd Taiwan Youth League\nThe Taichung Blue Whale U18 girls'' team took part in the 2nd Taiwan Youth League\nTook on the Sports iTaiwan sports hotspot promotion programme"}},{"date":"2022","title":{"zh":"2022 年","en":"2022"},"description":{"zh":"參加第九屆台灣木蘭足球聯賽\n代表台灣參加 AFC 女子足球俱樂部錦標賽(泰國)\n史上第三位泰國籍選手席拉萬茵樂敏加入\n疫情有成舉辦首場頂級足球開門賽\n台中藍鯨 U15 女子足球隊參加第三屆台灣青年聯賽\n台中藍鯨 U18 女子足球隊參加第三屆台灣青年聯賽\n台中藍鯨 U15 獲得第一座台灣青年聯賽 U15 女子組冠軍\n隊史第二座台灣木蘭聯賽亞軍\n承接運動 i 台灣-運動熱區推廣計畫","en":"Took part in the 9th Taiwan Mulan Football League\nRepresented Taiwan at the AFC Women''s Club Championship (Thailand)\nThird Thai player in club history, 席拉萬茵樂敏, joined\nAfter successfully managing the pandemic, held the first top-level football opening match\nThe Taichung Blue Whale U15 girls'' team took part in the 3rd Taiwan Youth League\nThe Taichung Blue Whale U18 girls'' team took part in the 3rd Taiwan Youth League\nThe Taichung Blue Whale U15 team won its first Taiwan Youth League U15 girls'' title\nSecond Taiwan Mulan League runners-up finish in club history\nTook on the Sports iTaiwan sports hotspot promotion programme"}},{"date":"2023","title":{"zh":"2023 年","en":"2023"},"description":{"zh":"參加第十屆台灣木蘭足球聯賽\n台中足球園區動土並獲邀參加動土典禮\n選手蘇育萱輸出旅外中國成功\n史上第四位泰國籍選手席菲拉萬茵樂敏加入\n史上第五位泰國籍選手薩瓦拉克彭甘加入\nFB 粉絲人數達 16500 人\n隊史第五座台灣木蘭聯賽冠軍\n承接運動 i 台灣-運動熱區推廣計畫","en":"Took part in the 10th Taiwan Mulan Football League\nBroke ground on the Taichung football park and was invited to the groundbreaking ceremony\nPlayer 蘇育萱 successfully moved abroad to China\nFourth Thai player in club history, 席菲拉萬茵樂敏, joined\nFifth Thai player in club history, 薩瓦拉克彭甘, joined\nFacebook followers reached 16,500\nFifth Taiwan Mulan League title in club history\nTook on the Sports iTaiwan sports hotspot promotion programme"}},{"date":"2024","title":{"zh":"2024 年","en":"2024"},"description":{"zh":"參加第十一屆台灣木蘭足球聯賽\n成立台中藍鯨 U10 女子隊\n台中藍鯨 U10 女子隊首次參加臺中市市長盃\n獲邀參加陽信盃國際邀請賽並獲得冠軍\n代表台灣參加 24/25 年亞足聯女子冠軍聯賽並順利小組晉級\n隊史第三座台灣木蘭聯賽亞軍\n史上第六位泰國籍選手第二位守門員瓦拉邦汶廷加入\n隊史第二位外籍選手薩瓦拉克彭甘獲得台灣木蘭足球聯賽年度金靴獎\n承接運動 i 台灣-運動熱區推廣計畫","en":"Took part in the 11th Taiwan Mulan Football League\nFounded the Taichung Blue Whale U10 girls'' team\nThe Taichung Blue Whale U10 girls'' team took part in the Taichung Mayor''s Cup for the first time\nInvited to the 陽信盃 international invitational tournament and won the title\nRepresented Taiwan in the 2024/25 AFC Women''s Champions League and advanced from the group stage\nThird Taiwan Mulan League runners-up finish in club history\nSixth Thai player in club history and second Thai goalkeeper, 瓦拉邦汶廷, joined\nThe club''s second foreign player, 薩瓦拉克彭甘, won the Taiwan Mulan Football League Golden Boot of the year\nTook on the Sports iTaiwan sports hotspot promotion programme"}},{"date":"2025","title":{"zh":"2025 年","en":"2025"},"description":{"zh":"參加第十二屆台灣木蘭足球聯賽\n代表台灣參加 2024 年至 2025 年亞足聯女子冠軍聯賽 8 強賽獲得亞洲前 8 名成績\n2025 台灣總統盃足球錦標賽亞軍\n史上第七位泰國籍選手第三位守門員邱瑪尼-通蒙戈加入\n史上第二位泰國籍選手冼仲意加入\n總教練呂桂花獲得 AFC 亞足聯亞洲最佳女足隊教練提名\n球衣首次放上公益團體機關台中惠明盲校\n承接運動 i 台灣-運動熱區推廣計畫\n首次接受英國世界足球雜誌專訪","en":"Took part in the 12th Taiwan Mulan Football League\nRepresented Taiwan in the 2024-25 AFC Women''s Champions League quarter-finals and finished among the top 8 in Asia\nRunners-up at the 2025 Taiwan President''s Cup football tournament\nSeventh Thai player in club history and third Thai goalkeeper, 邱瑪尼-通蒙戈, joined\nSecond Thai player in club history, 冼仲意, joined\nHead coach 呂桂花 was nominated for the AFC Asian Best Women''s Team Coach award\nFor the first time, the team shirt carried a public-interest organisation: 台中惠明盲校, a school for the blind in Taichung\nTook on the Sports iTaiwan sports hotspot promotion programme\nFirst interview with the British magazine World Soccer"}}]}', 0);
  INSERT INTO page_blocks (id, page_id, block_type, content, sort_order) VALUES (NEWID(), @id, N'text', N'{"body":{"zh":"上列沿革整理自舊官網公開內容，部分年度屆數標示與其他資料有出入，正式版本將於俱樂部確認後更新。","en":"The history above is compiled from content published on the former official website. The edition numbers of some seasons differ from other sources and will be updated once the club has confirmed them."}}', 1);
